 {"id": "PEDS-C43-049", "sec": "GHD investigations and treatment", "page": 200, "q": "The binding-protein assay noted for sensitivity in GHD screening is —", "opts": ["Transcortin", "IGFBP-3", "IGFBP-1", "IGFBP-2"], "ans": 1, "exp": "IGF BP-3 (binding protein) levels — noted for sensitivity. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-050", "sec": "GHD investigations and treatment", "page": 200, "q": "Preferred screening test for GHD when severe malnutrition is present —", "opts": ["Random GH", "IGF-2", "IGFBP-3", "IGF-1"], "ans": 2, "exp": "IGFBP-3 is preferred when associated with severe malnutrition (as IGF-1 is altered by malnutrition). (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-051", "sec": "GHD investigations and treatment", "page": 200, "q": "Confirmatory test for GH deficiency is —", "opts": ["Random GH estimation", "IGF-1 alone", "MRI pituitary", "Stimulative/provocative GH testing"], "ans": 3, "exp": "Confirmatory: GH estimation by stimulative/provocative GH testing. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-052", "sec": "GHD investigations and treatment", "page": 200, "q": "Random GH estimation is unreliable because GH is released —", "opts": ["In a pulsatile manner", "Only after meals", "Only during illness", "Only in deep sleep"], "ans": 0, "exp": "Random estimation is unreliable as GH is released in a pulsatile manner. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-053", "sec": "GHD investigations and treatment", "page": 200, "q": "Which agent is NOT listed among provocative substances for GH stimulation testing?", "opts": ["Arginine", "Metformin", "Insulin", "Clonidine"], "ans": 1, "exp": "Provocative substances listed: insulin, clonidine, arginine. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-054", "sec": "GHD investigations and treatment", "page": 200, "q": "After provocative testing, GH below ___ ng/ml is diagnostic of GH deficiency.", "opts": ["40", "5", "10", "20"], "ans": 2, "exp": "GH < 10 ng/ml after the test is diagnostic. (Book p200)", "type": "fill"},
 {"id": "PEDS-C43-055", "sec": "GHD investigations and treatment", "page": 200, "q": "A short child undergoes insulin-tolerant GH stimulation; peak GH is 6 ng/ml. This is —", "opts": ["Normal response", "Indeterminate, repeat later", "Suggests Laron dwarfism", "Diagnostic of GHD"], "ans": 3, "exp": "Stimulated GH < 10 ng/ml is diagnostic of GH deficiency. (Book p200)", "type": "case", "stem": "A 6-year-old with proportionate short stature (GV 3 cm/yr, delayed bone age) undergoes clonidine-stimulated GH testing. Peak GH is 6 ng/ml and IGF-1 is low."},
 {"id": "PEDS-C43-056", "sec": "GHD investigations and treatment", "page": 200, "q": "Treatment of GH deficiency uses —", "opts": ["Recombinant GH", "Cadaveric GH", "GH-releasing peptide only", "IGF-2 infusions"], "ans": 0, "exp": "Treatment: rGH (recombinant GH). (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-057", "sec": "GHD investigations and treatment", "page": 200, "q": "Recombinant GH is given by which route?", "opts": ["Intranasal", "Subcutaneous injection", "Intramuscular injection", "Oral"], "ans": 1, "exp": "Subcutaneous injection (usually given at night). (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-058", "sec": "GHD investigations and treatment", "page": 200, "q": "The usual time of day for rGH injection is —", "opts": ["Before lunch", "No specific timing", "Night", "Morning"], "ans": 2, "exp": "Usually given at night (mimicking physiological nocturnal GH pulses). (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-059", "sec": "GHD investigations and treatment", "page": 200, "q": "rGH therapy in GHD is continued until —", "opts": ["Height reaches mid-parental height", "Age 18 years", "IGF-1 normalises", "Epiphyseal closure"], "ans": 3, "exp": "Subcutaneous rGH until epiphyseal closure. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-060", "sec": "GHD investigations and treatment", "page": 200, "q": "On starting rGH, a child with GHD characteristically shows —", "opts": ["Catch-up growth", "Immediate cessation of growth", "Only weight loss", "No growth response"], "ans": 0, "exp": "Treatment shows catch-up growth. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-061", "sec": "GHD investigations and treatment", "page": 200, "q": "The mnemonic for other uses of rGH is ___.", "opts": ["GIANT SP", "GTCS IN P", "GIFT CHOP", "GHD TRIP"], "ans": 1, "exp": "Other uses of rGH: \"GTCS IN Prader-Willi syndrome\". (Book p200)", "type": "fill"},
 {"id": "PEDS-C43-062", "sec": "GHD investigations and treatment", "page": 200, "q": "In the rGH mnemonic \"GTCS IN P\", the letter T stands for —", "opts": ["Thalassaemia", "Tuberculosis", "Turner syndrome", "Trisomy 21"], "ans": 2, "exp": "T: Turner syndrome. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-063", "sec": "GHD investigations and treatment", "page": 200, "q": "In \"GTCS IN P\", the letter C stands for —", "opts": ["Celiac disease", "Cancer", "Crohn disease", "CKD"], "ans": 3, "exp": "C: CKD (chronic kidney disease). (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-064", "sec": "GHD investigations and treatment", "page": 200, "q": "In \"GTCS IN P\", S stands for SGA — small for gestational age beyond —", "opts": ["2 years", "1 year", "5 years", "6 months"], "ans": 0, "exp": "S: SGA (small for gestational age) > 2 years, associated with SHOX gene mutation. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-065", "sec": "GHD investigations and treatment", "page": 200, "q": "The gene linked with SGA-related short stature in the rGH indications is —", "opts": ["IGF1", "SHOX", "GH1", "GHRH-R"], "ans": 1, "exp": "SGA > 2 years (with SHOX gene mutation) is an rGH indication. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-066", "sec": "GHD investigations and treatment", "page": 200, "q": "In \"GTCS IN P\", the letters I, N and P stand for —", "opts": ["Insulin, Nephritis, Puberty", "Idiopathic, Narcolepsy, PWS", "Idiopathic, Noonan, Prader-Willi", "Iodine, Neuroblastoma, Pituitary"], "ans": 2, "exp": "I: idiopathic; N: Noonan syndrome; P: Prader-Willi syndrome. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-067", "sec": "GHD investigations and treatment", "page": 200, "q": "Match the rGH indication with the \"GTCS IN P\" letter:", "opts": ["A-1, B-3, C-2, D-4", "A-4, B-3, C-1, D-2", "A-4, B-1, C-3, D-2", "A-3, B-1, C-4, D-2"], "ans": 3, "exp": "Correct pairs: G→GH deficiency; T→Turner syndrome; C→CKD; N→Noonan syndrome. (Book p200)", "type": "match", "pairs": [["G", "Turner syndrome"], ["T", "Noonan syndrome"], ["C", "GH deficiency"], ["N", "CKD"]]},
 {"id": "PEDS-C43-068", "sec": "GHD investigations and treatment", "page": 200, "q": "Odd one out (indications for recombinant GH other than GHD):", "opts": ["Congenital adrenal hyperplasia", "Chronic kidney disease", "Turner syndrome", "Prader-Willi syndrome"], "ans": 0, "exp": "CAH is not in the GTCS-IN-P list; Turner, Prader-Willi and CKD are rGH indications. (Book p200)", "type": "odd"},
 {"id": "PEDS-C43-069", "sec": "GHD investigations and treatment", "page": 200, "q": "IGFBP-3 is preferred over IGF-1 for GHD screening when severe malnutrition coexists.", "opts": ["True", "False"], "ans": 0, "exp": "True — IGF-1 levels are altered by malnutrition, so IGFBP-3 is preferred in that setting. (Book p200)", "type": "tf"},
 {"id": "PEDS-C43-070", "sec": "Congenital hypothyroidism etiology and features", "page": 200, "q": "Early detection of hypothyroidism is most critical during —", "opts": ["Adolescence", "Any time before 10 years", "The first few years", "The first week only"], "ans": 2, "exp": "Importance of early detection (first few years): the thyroid is integral in brain development. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-071", "sec": "Congenital hypothyroidism etiology and features", "page": 200, "q": "The thyroid gland is integral to which developmental process?", "opts": ["Bone marrow development", "Lung maturation", "Renal tubular maturation", "Brain development"], "ans": 3, "exp": "Thyroid is integral in brain development — hence low IQ if undetected. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-072", "sec": "Congenital hypothyroidism etiology and features", "page": 200, "q": "Untreated congenital hypothyroidism leads to —", "opts": ["Low IQ", "High IQ", "Normal IQ with short stature", "Only goitre"], "ans": 0, "exp": "Low IQ if undetected and untreated. (Book p200)", "type": "mcq"},
 {"id": "PEDS-C43-073", "sec": "Congenital hypothyroidism etiology and features", "page": 200, "q": "Hypothyroidism is the most common ___ cause of intellectual disability.", "opts": ["Postnatal", "Preventable", "Genetic", "Perinatal"], "ans": 1, "exp": "Congenital hypothyroidism: m/c preventable cause of intellectual disability. (Book p200)", "type": "fill"},
 {"id": "PEDS-C43-074", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Primary hypothyroidism indicates pathology in the —", "opts": ["Pituitary", "Peripheral tissues", "Thyroid gland", "Hypothalamus"], "ans": 2, "exp": "Primary: pathology in thyroid gland; central: pathology in CNS (hypothalamus). (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-075", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Central hypothyroidism indicates pathology in the —", "opts": ["Thyroid gland", "Kidney", "Liver", "CNS (hypothalamus)"], "ans": 3, "exp": "Central: pathology in CNS/hypothalamus. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-076", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "The overall most common cause of congenital hypothyroidism is —", "opts": ["Thyroid dysgenesis", "Dyshormonogenesis", "Iodine deficiency", "Maternal antibodies"], "ans": 0, "exp": "Thyroid dysgenesis (anomaly) is the m/c cause overall. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-077", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Thyroid dysgenesis is typically —", "opts": ["Autosomal dominant", "Sporadic", "Autosomal recessive", "X-linked"], "ans": 1, "exp": "Thyroid dysgenesis: m/c cause overall and sporadic. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-078", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Forms of thyroid dysgenesis include aplasia, hypoplasia and —", "opts": ["Diffuse goitre", "Thyroiditis", "Ectopic thyroid", "Cystic thyroid"], "ans": 2, "exp": "Dysgenesis: aplasia, hypoplasia, ectopic thyroid. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-079", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "The most common site of ectopic thyroid is —", "opts": ["Substernal", "Ovarian", "Intrathoracic", "Lingual"], "ans": 3, "exp": "Ectopic thyroid (m/c site: lingual). (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-080", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Thyroid dyshormonogenesis most commonly involves defects in —", "opts": ["Organification", "Iodide trapping", "Proteolysis", "Thyroglobulin export"], "ans": 0, "exp": "Dyshormonogenesis: defects in organification (m/c) → thyroid peroxidase deficiency. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-081", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "The enzyme deficient in the most common form of dyshormonogenesis is —", "opts": ["Pendrin", "Thyroid peroxidase", "Thyroglobulin synthase", "Deiodinase"], "ans": 1, "exp": "Organification defects (m/c) → thyroid peroxidase deficiency. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-082", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Inheritance of thyroid dyshormonogenesis is —", "opts": ["X-linked recessive", "Mitochondrial", "Autosomal recessive", "Autosomal dominant"], "ans": 2, "exp": "Dyshormonogenesis: autosomal recessive inheritance. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-083", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Severe iodine deficiency causes endemic goitre/cretinism and is seen in —", "opts": ["Coastal populations", "High-altitude regions", "Industrialised nations", "Underdeveloped countries"], "ans": 3, "exp": "Severe iodine deficiency is seen in underdeveloped countries. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-084", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Maternal causes of congenital hypothyroidism include transplacental transfer of —", "opts": ["TSH receptor blocking antibody", "TSH receptor stimulating antibody", "Thyroxine-binding globulin", "Anti-insulin antibodies"], "ans": 0, "exp": "Maternal cause: transplacental transfer of TSH receptor blocking antibody. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-085", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "A maternal cause of neonatal hypothyroidism other than blocking antibodies is —", "opts": ["Antibiotics", "Antithyroid drugs", "Iron supplements", "Calcium supplements"], "ans": 1, "exp": "Maternal causes: TSH-receptor blocking antibody and antithyroid drugs. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-086", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Features of congenital hypothyroidism are difficult to identify in the first week because of masking by —", "opts": ["Neonatal TSH surge", "Brown fat activity", "Maternal thyroid hormones", "Fetal cortisol"], "ans": 2, "exp": "Difficult to identify in early newborn period (1st week) d/t masking by maternal thyroid hormones. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-087", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Congenital hypothyroidism features become evident after —", "opts": ["1 day", "1 month", "3 months", "1 week"], "ans": 3, "exp": "Features appear > 1 week, once maternal hormone masking wanes. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-088", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "The first listed feature of CH after the first week is —", "opts": ["Decreased activity of the child", "Macroglossia", "Umbilical hernia", "Hoarse cry"], "ans": 0, "exp": "Feature 1: decreased activity of the child. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-089", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "A wide open posterior fontanelle in CH is defined as greater than ___", "opts": ["3 cm", "5 mm", "1 cm", "2 mm"], "ans": 1, "exp": "Wide open posterior fontanelle: > 5 mm. (Book p201)", "type": "fill"},
 {"id": "PEDS-C43-090", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Skin findings in congenital hypothyroidism are —", "opts": ["Flushed skin", "Photosensitive rash", "Cold, dry skin", "Warm, moist skin"], "ans": 2, "exp": "Cold dry skin and hypothermia. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-091", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Constipation with delayed passage of ___ is a CH feature.", "opts": ["Stool after weaning", "Urine", "Feeds", "Meconium"], "ans": 3, "exp": "Constipation/delay in passage of meconium. (Book p201)", "type": "fill"},
 {"id": "PEDS-C43-092", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Macroglossia in congenital hypothyroidism is due to deposition of —", "opts": ["Mucopolysaccharides", "Amyloid", "Iron", "Calcium"], "ans": 0, "exp": "Macroglossia: increased mucopolysaccharides deposited in the tongue. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-093", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "The abdominal wall feature of congenital hypothyroidism is —", "opts": ["Inguinal hernia", "Umbilical hernia", "Diastasis recti", "Omphalocele"], "ans": 1, "exp": "Umbilical hernia. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-094", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "A 3-week-old neonate is lethargic with cold dry skin, wide posterior fontanelle, macroglossia, umbilical hernia, hoarse cry and prolonged jaundice. Most likely diagnosis —", "opts": ["Neonatal sepsis", "Prader-Willi syndrome", "Congenital hypothyroidism", "Congenital adrenal hyperplasia"], "ans": 2, "exp": "Lethargy + wide posterior fontanelle + macroglossia + umbilical hernia + hoarse cry + prolonged jaundice after the first week = congenital hypothyroidism. (Book p201)", "type": "case", "stem": "A 24-day-old infant has decreased activity, hypothermia with cold dry skin, constipation since birth, a large tongue, umbilical hernia and a hoarse cry. Jaundice has persisted for 3 weeks."},
 {"id": "PEDS-C43-095", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Goitre is usually ABSENT in congenital hypothyroidism due to —", "opts": ["Dyshormonogenesis", "Maternal antithyroid drugs", "Iodine deficiency", "Thyroid dysgenesis"], "ans": 3, "exp": "Goitre usually absent in thyroid dysgenesis (gland is absent/ectopic). (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-096", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Goitre CAN be present in congenital hypothyroidism with dyshormonogenesis or —", "opts": ["Maternal antithyroid drug usage", "Lingual thyroid", "Thyroid aplasia", "Central hypothyroidism"], "ans": 0, "exp": "Goitre can be present in dyshormonogenesis and maternal antithyroid drug usage. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-097", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Match the congenital hypothyroidism cause with its detail:", "opts": ["A-3, B-2, C-1, D-4", "A-2, B-3, C-4, D-1", "A-4, B-1, C-3, D-2", "A-4, B-1, C-2, D-3"], "ans": 1, "exp": "Correct pairs: Thyroid dysgenesis→M/c cause overall, sporadic; Ectopic thyroid→M/c site lingual; Dyshormonogenesis→TPO defect, autosomal recessive; Maternal antibodies→TSH-receptor blocking antibody. (Book p201)", "type": "match", "pairs": [["Thyroid dysgenesis", "TSH-receptor blocking antibody"], ["Ectopic thyroid", "M/c cause overall, sporadic"], ["Dyshormonogenesis", "M/c site lingual"], ["Maternal antibodies", "TPO defect, autosomal recessive"]]},
 {"id": "PEDS-C43-098", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Odd one out (congenital hypothyroidism features after 1 week):", "opts": ["Hoarse cry", "Macroglossia", "Wide open anterior fontanelle only", "Umbilical hernia"], "ans": 2, "exp": "The fontanelle finding is a wide-open POSTERIOR fontanelle (> 5 mm); the other three are listed CH features. (Book p201)", "type": "odd"},
 {"id": "PEDS-C43-099", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Thyroid dyshormonogenesis follows autosomal dominant inheritance.", "opts": ["True", "False"], "ans": 1, "exp": "False — Dyshormonogenesis is autosomal recessive. (Book p201)", "type": "tf"},
 {"id": "PEDS-C43-100", "sec": "Congenital hypothyroidism etiology and features", "page": 201, "q": "Congenital hypothyroidism is usually clinically obvious in the first week of life.", "opts": ["True", "False"], "ans": 1, "exp": "False — It is difficult to identify in the 1st week d/t masking by maternal thyroid hormones; features appear after 1 week. (Book p201)", "type": "tf"},
 {"id": "PEDS-C43-101", "sec": "CH investigations and treatment", "page": 201, "q": "Thyroid function tests in primary congenital hypothyroidism show —", "opts": ["Decreased T3 with decreased TSH", "Decreased T3, decreased free T4, increased TSH", "Increased T3, increased T4, decreased TSH", "Normal T3 with increased TSH"], "ans": 1, "exp": "TFT: decreased T3, decreased free T4, increased TSH. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-102", "sec": "CH investigations and treatment", "page": 201, "q": "Thyroid function testing as screening is done in —", "opts": ["Only preterm infants", "Only high-risk pregnancies", "All infants", "Only symptomatic infants"], "ans": 2, "exp": "Screening (infants): done in all infants. (Book p201)", "type": "mcq"},
 {"id": "PEDS-C43-103", "sec": "CH investigations and treatment", "page": 201, "q": "Newborn thyroid screening uses the heel-prick dried ___ spot.", "opts": ["Urine", "Saliva", "CSF", "Blood"], "ans": 3, "exp": "Heel prick dried blood spot testing. (Book p201)", "type": "fill"},
 {"id": "PEDS-C43-104", "sec": "CH investigations and treatment", "page": 202, "q": "TSH screening for congenital hypothyroidism is best done at —", "opts": ["3–4 days after birth", "Day 1 of life", "2 weeks after birth", "6 weeks after birth"], "ans": 0, "exp": "TSH: 3–4 days after birth (after the physiological TSH surge settles). (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-105", "sec": "CH investigations and treatment", "page": 202, "q": "A screening TSH above ___ mU/L mandates sending a thyroid function test.", "opts": ["100", "40", "20", "10"], "ans": 1, "exp": "TSH > 40 mU/L → send TFT. (Book p202)", "type": "fill"},
 {"id": "PEDS-C43-106", "sec": "CH investigations and treatment", "page": 202, "q": "Once congenital hypothyroidism is confirmed on TFT, the next step is —", "opts": ["Repeat TFT at 1 month", "Confirm with MRI brain", "Start treatment stat", "Wait for symptoms"], "ans": 2, "exp": "Confirmed CH → start treatment stat. (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-107", "sec": "CH investigations and treatment", "page": 202, "q": "A newborn screen on day 4 shows TSH 60 mU/L. Next step —", "opts": ["Reassure and repeat at 6 weeks", "Start iodine supplements", "Order a skull X-ray", "Send TFT and start treatment once confirmed"], "ans": 3, "exp": "TSH > 40 mU/L → send TFT → start treatment stat. (Book p202)", "type": "case", "stem": "A heel-prick dried blood spot of a 4-day-old term neonate reports TSH 60 mU/L. The infant is asymptomatic."},
 {"id": "PEDS-C43-108", "sec": "CH investigations and treatment", "page": 202, "q": "Radiological assessment in congenital hypothyroidism shows delayed —", "opts": ["Bone age", "Dentition only", "Lung fields", "Skull sutures"], "ans": 0, "exp": "Radiological assessment: delayed bone age. (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-109", "sec": "CH investigations and treatment", "page": 202, "q": "Epiphyseal stippling/dysgenesis in CH appears as —", "opts": ["Subperiosteal new bone", "Dot-like structures at epiphysis", "Fraying of metaphysis", "Cupping of metaphysis"], "ans": 1, "exp": "Epiphyseal stippling/dysgenesis = dot-like structures at the epiphysis. (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-110", "sec": "CH investigations and treatment", "page": 202, "q": "The text remarks that the radiological findings (delayed bone age, epiphyseal stippling) are —", "opts": ["Specific for dysgenesis", "Specific for dyshormonogenesis", "Not diagnostic of hypothyroidism", "Diagnostic of hypothyroidism"], "ans": 2, "exp": "The radiological signs are flagged as not diagnostic of hypothyroidism; TFT is the diagnostic test. (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-111", "sec": "CH investigations and treatment", "page": 202, "q": "Confirmatory test to localise the thyroid as present, absent or ectopic is —", "opts": ["MRI neck", "CT neck", "Thyroid biopsy", "USG of thyroid"], "ans": 3, "exp": "USG of thyroid: present/absent/ectopic. (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-112", "sec": "CH investigations and treatment", "page": 202, "q": "Radionuclide study of the thyroid uses which radioisotope pair?", "opts": ["I-131 preferred over Tc-99m", "Tc-99m preferred over I-131", "I-123 only", "Gallium-67"], "ans": 0, "exp": "Radioisotope used: I-131 >> Tc-99m. (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-113", "sec": "CH investigations and treatment", "page": 202, "q": "Treatment of congenital hypothyroidism is —", "opts": ["Radioiodine ablation", "Oral thyroxine (T4)", "Oral T3 alone", "Transplacental T4"], "ans": 1, "exp": "Treatment: oral thyroxine (T4). (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-114", "sec": "CH investigations and treatment", "page": 202, "q": "Thyroxine in congenital hypothyroidism should be started —", "opts": ["Only when symptomatic", "After confirming the exact etiology", "As early as possible", "After 1 month of age"], "ans": 2, "exp": "To be started as early as possible. (Book p202)", "type": "mcq"},
 {"id": "PEDS-C43-115", "sec": "CH investigations and treatment", "page": 202, "q": "Dose of oral thyroxine in congenital hypothyroidism is ___ μg/kg/day", "opts": ["1–2 μg/kg/day", "3–5 μg/kg/day", "25–30 μg/kg/day", "10–15 μg/kg/day"], "ans": 3, "exp": "Dose: 10–15 μg/kg/day. (Book p202)", "type": "fill"},
